import{J as e,n as t,ot as n,q as r}from"./chunks/framework.DStH8c-G.js";var i=JSON.parse(`{"title":"Brand","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Brand"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/brand/"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/brand/"}]],"editSource":{"kind":"file","url":"https://github.com/JSPrismarine/JSPrismarine/edit/master/docs/brand/README.md"}},"headers":[],"relativePath":"brand/index.md","filePath":"brand/index.md","lastUpdated":1794459041000}`),a={name:`brand/index.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<div><h1 id="brand" tabindex="-1">Brand <a class="header-anchor" href="#brand" aria-label="Permalink to “Brand”">​</a></h1><p>How JSPrismarine looks and sounds. The docs site implements this guide, and the <a href="https://jsprismarine.dev/brand-kit" target="_blank" rel="noreferrer">brand kit</a> renders every color, the mark and each component live from the same source.</p><table tabindex="0"><thead><tr><th>What</th><th>Where</th></tr></thead><tbody><tr><td>Palette</td><td><code>tools/docs/site/.vitepress/theme/tokens.ts</code></td></tr><tr><td>Mark geometry</td><td><code>tools/docs/site/.vitepress/theme/prism.ts</code></td></tr><tr><td>Derived shades and sizes</td><td><code>tools/docs/site/.vitepress/theme/brand.css</code></td></tr><tr><td>Code colors</td><td><code>tools/docs/site/.vitepress/theme/codeTheme.ts</code></td></tr><tr><td>Components</td><td><code>tools/docs/site/.vitepress/theme/components/</code></td></tr><tr><td>Project facts</td><td><code>tools/docs/project.mts</code></td></tr><tr><td>Docs facts</td><td><code>tools/docs/facts.mts</code></td></tr><tr><td>Release notes</td><td><code>tools/docs/site/releases.data.mts</code></td></tr></tbody></table><h2 id="position" tabindex="-1">Position <a class="header-anchor" href="#position" aria-label="Permalink to “Position”">​</a></h2><p>JSPrismarine is the Bedrock server you run, own and build on. It is a product people choose, not a library index. The brand is flat, bold and direct: big type, solid color blocks, hard edges, and real commands and numbers instead of decoration.</p><p>Four audiences use the site. Each page should make clear which one it serves:</p><table tabindex="0"><thead><tr><th>Audience</th><th>Wants</th><th>Landing tab</th></tr></thead><tbody><tr><td>Players</td><td>Join a server and know what works</td><td>I play</td></tr><tr><td>Hosts</td><td>Install, configure and operate it</td><td>I host</td></tr><tr><td>Add-on devs</td><td>Packs, Molang and the package API</td><td>I build add-ons</td></tr><tr><td>Contributors</td><td>Clone, change, test and ship</td><td>I contribute</td></tr></tbody></table><h2 id="color" tabindex="-1">Color <a class="header-anchor" href="#color" aria-label="Permalink to “Color”">​</a></h2><p>The accent is <code><span class="color-swatch" style="--swatch:#5ca48a;" aria-hidden="true"></span>#5ca48a</code>, shared with the JSPrismarine website. Every other color supports it.</p><table tabindex="0"><thead><tr><th>Token</th><th>Hex</th><th>Use</th></tr></thead><tbody><tr><td><code>--jsp-accent</code></td><td><code><span class="color-swatch" style="--swatch:#5ca48a;" aria-hidden="true"></span>#5ca48a</code></td><td>Primary accent: buttons, highlights, active states.</td></tr><tr><td><code>--jsp-forest</code></td><td><code><span class="color-swatch" style="--swatch:#003829;" aria-hidden="true"></span>#003829</code></td><td>Dark brand surface and light-mode link color.</td></tr><tr><td><code>--jsp-deep</code></td><td><code><span class="color-swatch" style="--swatch:#00281d;" aria-hidden="true"></span>#00281d</code></td><td>Darkest surface: tile backgrounds and shadows.</td></tr><tr><td><code>--jsp-mint</code></td><td><code><span class="color-swatch" style="--swatch:#a9d9c6;" aria-hidden="true"></span>#a9d9c6</code></td><td>Body text on forest and the light facet of the mark.</td></tr><tr><td><code>--jsp-cream</code></td><td><code><span class="color-swatch" style="--swatch:#efe9da;" aria-hidden="true"></span>#efe9da</code></td><td>Light surface and text on dark.</td></tr><tr><td><code>--jsp-ink</code></td><td><code><span class="color-swatch" style="--swatch:#0b1713;" aria-hidden="true"></span>#0b1713</code></td><td>Text on light and the terminal surface.</td></tr><tr><td><code>--jsp-signal</code></td><td><code><span class="color-swatch" style="--swatch:#ff6b3d;" aria-hidden="true"></span>#ff6b3d</code></td><td>Spot color for prompts, cursors and the core of the mark.</td></tr></tbody></table><p><code>tokens.ts</code> is the authority for these values. The site config writes them into the page head as the <code>--jsp-*</code> custom properties and builds the favicon from them, and <code>brand.css</code> mixes the supporting shades (terminal chrome, progress tracks, page backgrounds, muted text) from them with <code>color-mix</code>. If this table and <code>tokens.ts</code> disagree, <code>tokens.ts</code> wins and this table is out of date.</p><p>Rules:</p><ul><li>Surfaces are flat. No gradients, glows, blurs or translucent glass. Two flat exceptions keep surfaces apart: a 1px hairline edge where two surfaces are close in value (code blocks and tables in dark mode, soft cards on the light page), and the flat ink scrim behind the open menu.</li><li>Blocks that touch differ in surface. The ticker is ink on the light page and <code>--jsp-deep</code> on the dark one, so it never merges with the accent tile above it. In dark mode a panel that holds cards is <code>--jsp-deep</code> and its cards are forest, so page, panel and card are three distinct levels.</li><li>Signal orange marks small things: a prompt, a cursor, the core of the mark, a focus ring, the rule beside a change that breaks or removes something, and the square beside a parity group under half passing. A page may also use it for one solid block. It is never a link color and never a body text color.</li><li>Text on <code>--jsp-accent</code> is <code>--jsp-deep</code>, through <code>--jsp-on-accent</code>. Forest on accent misses AA for body text, so forest stays on accent only in display type such as the hero&#39;s highlighted word. Text on <code>--jsp-signal</code> is <code>--jsp-ink</code>.</li><li>Small text on forest is <code>--jsp-mint</code>. Accent on forest is for figures and display type only.</li><li>Keep all text, muted text included, at WCAG AA contrast or better against its surface. The site&#39;s <code>--vp-c-text-2</code> and <code>--vp-c-text-3</code> are ink (or cream in dark mode) mixed down only as far as AA allows; reach for them instead of an opacity.</li></ul><h2 id="type" tabindex="-1">Type <a class="header-anchor" href="#type" aria-label="Permalink to “Type”">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Family</th><th>Weights</th><th>Notes</th></tr></thead><tbody><tr><td>Display</td><td>Bricolage Grotesque</td><td>500, 800</td><td>Tight tracking (<code>-0.04em</code> and below).</td></tr><tr><td>Mono</td><td>JetBrains Mono</td><td>400, 700</td><td>Commands, labels, logs and code.</td></tr></tbody></table><p>Headlines are set heavy and tight, in sentence case, and are allowed to be very large. Small labels are mono, uppercase and letter-spaced, and never smaller than <code>--jsp-label-size</code>: that holds for key hints, counts, dates, version tags and code-language labels too. Identifiers, such as package names (on the package cards, the API index and its sidebar) and parity family and group ids, are mono, never display type, whose tight tracking hides their dots. A display figure with dots in it, such as a version, opens its tracking to <code>-0.03em</code> for the same reason. System fonts are the fallback when the web fonts do not load.</p><h2 id="mark" tabindex="-1">Mark <a class="header-anchor" href="#mark" aria-label="Permalink to “Mark”">​</a></h2><p>The mark is a prism: a triangle split down the middle into an <code>--jsp-accent</code> face and a <code>--jsp-mint</code> face, with a small <code>--jsp-signal</code> triangle at its core whose right half is shaded with ink.</p><ul><li>Use <code>PrismMark</code> rather than redrawing it. The favicon and the nav logo come from the same geometry in <code>prism.ts</code>.</li><li>Keep clear space of half the mark&#39;s width on every side.</li><li>Do not rotate, outline, add shadows or recolor the faces. The mark works unchanged on cream, forest and ink, so it has no inverted version.</li><li>The wordmark is <code>JSPrismarine</code>: one word, camel case, set in Bricolage Grotesque 800.</li></ul><h2 id="shape-and-motion" tabindex="-1">Shape and motion <a class="header-anchor" href="#shape-and-motion" aria-label="Permalink to “Shape and motion”">​</a></h2><ul><li>Corners are <code>14px</code> on panels (<code>--jsp-radius-panel</code>) and <code>10px</code> on controls (<code>--jsp-radius-control</code>). Pills are fully round.</li><li>Primary actions carry a hard offset shadow (<code>4px 4px 0</code>, no blur). It shrinks on hover and disappears on press, so the button reads as pushed in. The shadow is ink on light surfaces and mint on forest and in dark mode (<code>--jsp-primary-shadow</code>), where an ink shadow would vanish. Secondary and outline buttons have no shadow: an edge alone, filled on hover, so only the primary action looks like a key to press.</li><li>A 2px edge marks a control (a tab, a button, a filter). A link card is a soft fill with a hairline and an arrow. Links inside a card are text links; only the card or its title may look clickable.</li><li>A state bar, such as the current section under the header or the current page in the sidebar, needs 3:1 against the page (<code>--jsp-state</code>). Accent on the light page falls short, so the bar is forest there and accent in dark mode.</li><li>A selected tab or filter pill is ink in light mode and accent in dark mode, so it stands apart from the accent figure tiles on the light page and from the ink surfaces on the dark one. A selectable tile, such as a parity group, is a figure tile and stays accent when selected.</li><li>Grids are tight: <code>10px</code> gaps (<code>--jsp-gap</code>) between solid blocks.</li><li>Every control shows a signal-orange focus ring when reached by keyboard, with an ink band between the control and the ring. Signal alone is too faint on the light page; with the band the ring reads on cream, forest, ink and signal surfaces alike. <code>brand.css</code> sets it once for every element.</li><li>On phones, controls are at least <code>--jsp-target</code> tall, the WCAG touch target size.</li><li>Motion is short and mechanical. Honor <code>prefers-reduced-motion</code> by stopping tickers and cursors. Anything that moves on its own also stops on hover and has a Pause button, for readers who have not set reduced motion. With a mouse, the button shows on hover, on keyboard focus and while paused; touch screens always show it.</li></ul><h2 id="code" tabindex="-1">Code <a class="header-anchor" href="#code" aria-label="Permalink to “Code”">​</a></h2><p>Code blocks sit on the terminal&#39;s ink surface in light and dark mode alike, so a command in the docs looks like the console it runs in. <code>codeTheme.ts</code> builds the syntax theme from <code>tokens.ts</code>: comments in the terminal&#39;s muted mint, keywords in accent, strings in mint, numbers and constants in signal, names in cream. Every token color keeps AA against ink. The copy button shows at rest, beside the language label, and at full strength where there is no hover. On phones, code wraps instead of scrolling off the screen edge, under a strip that holds the label and the copy button, and a two-column table stacks each row as its name over its value.</p><h2 id="doc-pages" tabindex="-1">Doc pages <a class="header-anchor" href="#doc-pages" aria-label="Permalink to “Doc pages”">​</a></h2><ul><li>Every doc page shares one column and one nav position, the parity tracker included. Root pages with no docs folder (packages, parity, releases, the brand kit) take their menu section&#39;s link groups as a sidebar. A section whose overview is a card page takes its sidebar from that page&#39;s groups, so the sidebar lists every page the overview offers, and the build fails on a page in the folder that the overview leaves out.</li><li>Every page ends on the site footer, doc pages beside a sidebar included. The footer carries the mark, the wordmark, the server version and the license, beside one link column per audience from the guide overview and a Project column (<code>footer.mts</code>), so it routes the way the menu does.</li><li>Each second-level section opens on a short solid bar over a display heading; a component&#39;s own headings (<code>vp-raw</code>) draw the same pair themselves, as the parity tracker&#39;s do. Overview pages whose sections are lists of links set those sections as cards (<code>sectionCards.ts</code>), on a grid that reads left to right in the page&#39;s order, at full width with no outline, since the cards are the outline. A card overview has no Next link at its foot: its cards are the way on.</li><li>Release notes lead each change with its first sentence in bold. Inline code in them is mono in the body color, without a chip, so accent still means a link. A breaking note folds behind one label, &quot;Breaking: what to update&quot;, on its signal rule, so the changes read as a list and upgraders open the details they need.</li><li>Inline code is never a green on the dark page; it is cream on its forest chip, so green still means a link.</li><li>The parity tracker&#39;s rows and group tiles mark anything under half passing with a signal square. Its status chips differ by shape as well as color, and only defects and failures are filled signal. Group tiles count the behavior checks when a group has them and its data-table rows otherwise, and say which with a unit word, so each tile agrees with the behavior score the home page shows. A case row sets its score, counts and bar on one line beside the family name, so the two share a baseline. On phones the group tiles become one-line rows, so the cases follow within a screen.</li><li>The package directory, the API reference index and its sidebar group packages by the areas in <code>packageAreas.ts</code>; the docs build fails when a published package has no area. The directory is where packages are described; the API index lists their names only, as a grid of links whose names never wrap or clip (cells at least 200 px wide, two to a row on phones), so the two pages do different jobs. When every package shares one npm scope, the directory names it once above the cards instead of on each.</li><li>Menu and search previews end on a whole sentence where one fits.</li><li>The header&#39;s controls (Search, and on phones the Menu button) are controls, not primary actions: an edge and no offset shadow. While the phone menu is open, its own search field replaces the header&#39;s search button, which keeps its space so Close stays where Menu was.</li></ul><h2 id="the-landing-page" tabindex="-1">The landing page <a class="header-anchor" href="#the-landing-page" aria-label="Permalink to “The landing page”">​</a></h2><ul><li>The hero says what JSPrismarine is in plain words beside the headline, shows facts the repository records (builds, protocol versions, default port, license), and offers one link per audience into the tabs below it (<code>#start-play</code>, <code>#start-host</code> and so on); phones get one line to the tabs.</li><li>Each audience tab is a card that names the audience with its tagline, so all four read before any click; one panel shows at a time, headed by what that audience gets.</li><li>The solid accent and signal figure tiles stay: they carry the page&#39;s character. Each shows a figure the hero does not.</li><li>The page ends on a call to action with a command to copy, plus a line for players and contributors, not on decoration. The footer under it routes by audience.</li></ul><h2 id="the-menu" tabindex="-1">The menu <a class="header-anchor" href="#the-menu" aria-label="Permalink to “The menu”">​</a></h2><p>The site has one menu, in <code>tools/docs/site/.vitepress/theme/site-menu/</code>, drawn from <code>megaMenus</code> in <code>menus.mts</code>. It follows these rules at every width:</p><ul><li><strong>It reads as a menu.</strong> Sections are labeled buttons with a chevron, Search is its own labeled button, and phones get a button that says Menu.</li><li><strong>It grows out of the header.</strong> The header&#39;s bottom edge is the panel&#39;s top edge. The open section&#39;s button becomes an ink tab that runs into the panel, and search opens in the header itself.</li><li><strong>Ink means open.</strong> The tab, the panel, the search field and, on phones, the header turn ink while the menu is open, and the panel ends on an accent rule. The dark header is nearly ink already, so in dark mode the open menu takes the deep surface instead.</li><li><strong>You leave where you entered.</strong> Close sits exactly where Menu was, and Esc returns focus to the button or field that opened the menu.</li><li><strong>It shows no key hints.</strong> The menu keeps the keyboard behavior of a disclosure menu, but only search, where the keys earn their place, shows a hint row. Shortcut labels follow the platform: ⌘ on Apple, Ctrl elsewhere, and <code>/</code> works on layouts that need Shift for it.</li><li><strong>It knows where you are.</strong> The current section carries the accent bar, the current page is highlighted, and a breadcrumb above the page names both. A section&#39;s index page counts as current in the first menu that lists pages in its folder, even when no menu links the index itself. When the menus link only to sections of the page being read, the first of those links marks it.</li><li>The Guides menu takes its groups and links from the guide overview (<code>overviewGroups.mts</code>), as the sidebar does, so the menu, the sidebar and the page always name the same audiences.</li></ul><h2 id="voice" tabindex="-1">Voice <a class="header-anchor" href="#voice" aria-label="Permalink to “Voice”">​</a></h2><ul><li>State what the thing does. &quot;One binary to host it.&quot; beats &quot;A powerful solution for hosting.&quot;</li><li>Prefer real commands, file names and numbers to adjectives. Never show a number the repository cannot back.</li><li>Address the reader directly and keep sentences short.</li><li>American English, sentence case headings, no exclamation marks, no emoji.</li></ul><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to “Components”">​</a></h2><p>The docs theme registers these Vue components globally, so any site page can use them without an import. Pages staged from <code>docs/</code> render as plain Markdown, so use the components from site-owned pages such as <code>tools/docs/site/index.md</code> and <code>tools/docs/site/brand-kit.md</code>.</p><table tabindex="0"><thead><tr><th>Component</th><th>Purpose</th></tr></thead><tbody><tr><td><code>PrismMark</code></td><td>The mark as inline SVG, at any size.</td></tr><tr><td><code>BrandButton</code></td><td>Primary, outline (on dark) and secondary (on the page) buttons.</td></tr><tr><td><code>TerminalWindow</code></td><td>A server console frame. Each <code>t-line</code> span in the slot is a line.</td></tr><tr><td><code>AudienceTabs</code></td><td>Keyboard-navigable tab cards with a pitch, a snippet and links each. <code>anchor</code> gives each panel a linkable id.</td></tr><tr><td><code>BentoGrid</code>, <code>BentoTile</code></td><td>Solid color tiles for short claims or figures.</td></tr><tr><td><code>ParityBars</code></td><td>The behavior parity score and bars, counted as the tracker counts.</td></tr><tr><td><code>CopyButton</code></td><td>Copies a command to the clipboard.</td></tr><tr><td><code>LatestRelease</code></td><td>The newest release&#39;s version, date and first changes.</td></tr><tr><td><code>ReleaseNotes</code></td><td>Release notes from the changelog, with long groups collapsed.</td></tr><tr><td><code>PackageDirectory</code></td><td>A filterable grid of the published packages.</td></tr><tr><td><code>Ticker</code></td><td>A looping banner of short phrases, with a Pause button.</td></tr></tbody></table><p>On doc pages, a hex color written as code, such as <code><span class="color-swatch" style="--swatch:#5ca48a;" aria-hidden="true"></span>#5ca48a</code>, renders with a chip of that color in front of it, in inline code and in highlighted code blocks alike. <code>.vitepress/colorSwatches.ts</code> adds the chip; a three- or four-digit value needs a letter, so issue numbers like <code>#123</code> stay plain.</p><h2 id="content-comes-from-the-repository" tabindex="-1">Content comes from the repository <a class="header-anchor" href="#content-comes-from-the-repository" aria-label="Permalink to “Content comes from the repository”">​</a></h2><p>The landing page states no fact that the repository already records. <code>project.data.mts</code> reads these at build time:</p><ul><li>the server version;</li><li>the published packages;</li><li>the Node and pnpm requirements;</li><li>the supported protocols and Minecraft releases;</li><li>the default port and online mode;</li><li>the release notes, from the server package&#39;s changelog.</li></ul><p>The build fails when a command, package or source pattern the page relies on disappears. The terminal preview uses the server&#39;s real startup log lines. <code>ParityBars</code> reads the tracker snapshot and shows the gameplay behavior score that the parity tracker page leads with, not the data-table pass rate. To add a claim to the page, add it to the loader rather than typing the value into a component.</p><p>Markdown pages follow the same rule through docs facts. A value the code owns is wrapped in a marker, such as <code>&lt;!-- fact:protocol.newest --&gt;2225&lt;!-- /fact --&gt;</code>, which GitHub hides. The docs build fills in the current value from <code>tools/docs/facts.mts</code>, so the site stays right when the code changes; <code>pnpm run docs:facts</code> refreshes the values in the Markdown.</p><h2 id="changing-the-brand" tabindex="-1">Changing the brand <a class="header-anchor" href="#changing-the-brand" aria-label="Permalink to “Changing the brand”">​</a></h2><p>Change a color in <code>tokens.ts</code>, a shape in <code>prism.ts</code>, and a derived value in <code>brand.css</code>, never a hex value in a component. Update this guide in the same commit when a token, font or rule changes.</p></div>`,1)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};